    {
      "id": "r3",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अथ सम्पत्प्राप्त्यरिविजयाद्यकिंचित्करमेव नास्ति तस्मात्परमार्थलाभ इत्याह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "प्राप्ताः श्रियः सकलकामदुघास्ततः किं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "दत्तं[१] पदं शिरसि विद्विषतां ततः किम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "संमानिताः प्रणयिनो विभवैस्ततः किं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "कल्पं[२] स्थितं तनुभृतां तनुभिस्ततः किम् ॥ ६८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "सकलान् कामान् दुहन्तीति ताः श्रियः प्राप्ताः ततः किम् । न काचित्पुरुषा-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "र्थसिद्धिः । एवं सर्वत्र । विद्विषतां शत्रूणाम् । प्रणयिनः सेवकाः मित्राणि वा ।",
          "end": "space"
        },
        {
          "n": 3,
          "text": "विभवैः गजतुरगालंकारादिसंपत्तिभिः संमानिताः बहुमानिताः । तनुभृतां",
          "end": "space"
        },
        {
          "n": 4,
          "text": "देहिनां तनुभिः शरीरैः । कल्पं ‘कालाध्वनोरत्यन्तसंयोगे’ इति द्वितीया । स्थितं ।",
          "end": "space"
        },
        {
          "n": 5,
          "text": "निरतिशयानन्दपर्यन्तं सर्वस्य सातिशयत्वात् अवश्यविनाशित्वाच्च । इतः श्लोक-",
          "end": "hyphen"
        },
        {
          "n": 6,
          "text": "चतुष्टयस्य वसन्ततिलका वृत्तम् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "तर्हि किं श्रेयःसाधनमित्याह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "भक्तिर्भवे मरणजन्मभयं हृदिस्थं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स्नेहो न बन्धुषु न मन्मथजा विकाराः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "संसर्गदोषरहिता विजना वनान्ता",
          "end": "line"
        },
        {
          "n": 4,
          "text": "वैराग्यमस्ति किमतः परमर्थनीयम् ॥ ६९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "भवे शिवे । मरणं च जन्म च ताभ्यां भयं हृदिस्थं हृच्छयम् । बन्धुषु",
          "end": "space"
        },
        {
          "n": 2,
          "text": "प्रणयिषु स्नेहः प्रेम । मन्मथजाः पुष्पधन्वनो जाता विकाराः चित्तदोषा अपि",
          "end": "space"
        },
        {
          "n": 3,
          "text": "न । तेषां श्रेयःप्रतिबन्धकत्वात् । संसर्गदोषः कालुष्यं तेन रहिताः । काम-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "क्रोधादिदोषवर्जिता इत्यर्थः । विजनाः निर्जनाश्च । वनान्ताः वनमध्यस्थानानि ।",
          "end": "space"
        },
        {
          "n": 5,
          "text": "वैराग्यं विरक्तिः । अतः परं वैराग्यात्परं किमन्यदर्थनीयं प्रार्थनीयमस्ति । न",
          "end": "space"
        },
        {
          "n": 6,
          "text": "किञ्चिदपि । तस्यैव श्रेयःपरमसाधनत्वात् ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r9",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अथ वैराग्यसम्पन्नेन ब्रह्मचिन्तनपरेण भवितव्यं यतो ब्रह्मैकध्यानपरस्य भुव-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "नाधिपत्यादयो भोगास्तुच्छा एव प्रतिभान्तीत्याह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r10",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "तस्मादनन्तमजरं परमं विकासि",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तद्ब्रह्म[३] चिन्तय किमेभिरसद्विकल्पैः ।",
          "end": "line"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r11",
      "type": "footnote",
      "lines": [
        {
          "n": 1,
          "text": "१ न्यस्तं.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
