          "n": 1,
          "text": "२ कल्पस्थिताः...तनवः ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r13",
      "type": "footnote",
      "lines": [
        {
          "n": 1,
          "text": "३ तद्ब्रह्म वाञ्छत जना यदि चेतनस्थाः.",
          "end": "space"
        }
      ],
